import { randomUUID } from 'node:crypto';
import { createWriteStream } from 'node:fs';
import { mkdir, open, rename, rm, stat } from 'node:fs/promises';
import { join } from 'node:path';
import { Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { CourseError } from '../courses/errors';

export const MAX_VIDEO_BYTES = 200 * 1024 * 1024;

/** Storage keys are generated by us; anything else is rejected before it can reach the file system. */
export const storageKeyPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.mp4$/;

const invalid = (message: string) =>
  new CourseError('invalid_content', [{ code: 'schema', message }]);

export function mediaPath(storageDir: string, key: string) {
  if (!storageKeyPattern.test(key)) throw new CourseError('media_not_found');
  return join(storageDir, key);
}

/** Saves an uploaded mp4 under a new key. The file is checked and size-limited while it is written. */
export async function saveVideo(
  storageDir: string,
  body: ReadableStream<Uint8Array> | AsyncIterable<Uint8Array> | Iterable<Uint8Array>,
  maxBytes = MAX_VIDEO_BYTES,
): Promise<{ key: string; size: number }> {
  await mkdir(storageDir, { recursive: true });
  const key = `${randomUUID()}.mp4`;
  const tmp = join(storageDir, `${key}.part`);
  let size = 0;
  const limit = new Transform({
    transform(chunk: Buffer, _enc, cb) {
      size += chunk.length;
      cb(size > maxBytes ? invalid('The video is too large.') : null, chunk);
    },
  });
  try {
    await pipeline(body as Iterable<Uint8Array>, limit, createWriteStream(tmp));
    if (size === 0) throw invalid('The video file is empty.');
    // An mp4 starts with a box whose type, at bytes 4-8, is "ftyp".
    const head = Buffer.alloc(8);
    const file = await open(tmp, 'r');
    try {
      await file.read(head, 0, 8, 0);
    } finally {
      await file.close();
    }
    if (head.subarray(4, 8).toString('latin1') !== 'ftyp')
      throw invalid('The file is not an mp4 video.');
    await rename(tmp, join(storageDir, key));
  } catch (err) {
    await rm(tmp, { force: true });
    throw err;
  }
  return { key, size };
}

export async function statVideo(storageDir: string, key: string) {
  const path = mediaPath(storageDir, key);
  try {
    return { path, size: (await stat(path)).size };
  } catch {
    throw new CourseError('media_not_found');
  }
}
